#import <Metal/Metal.h>
#import <mach/mach_time.h>
#include "cost.h"
#include <vector>
#include <mutex>
#include <atomic>
#include <cstdio>
#include <cstdlib>
struct interval { char tag; uint64_t a,b; };
struct command { char tag; id<MTLCommandBuffer> cb; };
static std::mutex mu;
static std::vector<interval> spans;
static std::vector<command> cmds;
static std::atomic<bool> on;
static std::atomic<uint64_t> bytes[3],nr,nd,nl;
static thread_local int expert;
static uint64_t started;
static int step;
int cost_active(){return on.load(std::memory_order_relaxed);}
uint64_t cost_now(){return clock_gettime_nsec_np(CLOCK_UPTIME_RAW);}
void cost_set_expert(int x){expert=x;}
void cost_cb(void *obj){if(cost_active()){std::lock_guard lock(mu);cmds.push_back({expert?'G':'M',(__bridge id<MTLCommandBuffer>)obj});}}
void cost_span(char tag,uint64_t a,uint64_t b){std::lock_guard lock(mu);spans.push_back({tag,a,b});}
void cost_bytes(int k,uint64_t n){if(cost_active())bytes[k].fetch_add(n,std::memory_order_relaxed);}
void cost_routes(int total,int distinct){if(cost_active()){nr+=total;nd+=distinct;++nl;}}
void cost_begin(int s){cmds.clear();spans.clear();for(auto &v:bytes)v=0;nr=nd=nl=0;step=s;started=cost_now();on=true;}
void cost_end(){uint64_t end=cost_now();on=false;
 static FILE *f=fopen(getenv("FLASH_COST_TRACE"),"w");if(!f)abort();
 fprintf(f,"B %d %llu %llu %llu %llu %llu %llu %llu %llu\n",step,started,end,bytes[0].load(),bytes[1].load(),bytes[2].load(),nr.load(),nd.load(),nl.load());
 for(auto &p:spans)fprintf(f,"%c %llu %llu\n",p.tag,p.a,p.b);
 for(auto &p:cmds){auto cb=p.cb;fprintf(f,"%c %.0f %.0f %lu\n",p.tag,cb.GPUStartTime*1e9,cb.GPUEndTime*1e9,(unsigned long)cb.status);}
 fputs("E\n",f);fflush(f);cmds.clear();spans.clear();}
